      reversePath(clipped);guide=clipped;
    }
  }
  if(style?.railLayout==='transfer'){
    const extent=clamp(c.mainEnd??.7,.2,1);
    let length=0;
    for(let i=2;i<main.length-2;i+=2)length+=Math.hypot(main[i+2]-main[i],main[i+3]-main[i+1]);
    let remaining=length*extent;
    const retained=main.slice(0,4);
    for(let i=2;i<main.length-2;i+=2){
      const length=Math.hypot(main[i+2]-main[i],main[i+3]-main[i+1]);
      if(remaining<=1e-9)break;
      if(remaining>=length){retained.push(main[i+2],main[i+3]);remaining-=length;}
      else{retained.push(lerp(main[i],main[i+2],remaining/length),lerp(main[i+1],main[i+3],remaining/length));break;}
    }
    main=retained;
  }
