  // Guide ids retain the original full-main offset even when a transfer
  // shortens its main support; orientation never changes the id range.
  return [{id, coordinates: main}, {id: id + mainCount, coordinates: guide}];
}

/** Reverse vertices while preserving each x,y pair. */
function reversePath(coordinates:number[]):void{
  for(let a=0,b=coordinates.length-2;a<b;a+=2,b-=2){
    const x=coordinates[a],y=coordinates[a+1];coordinates[a]=coordinates[b];coordinates[a+1]=coordinates[b+1];coordinates[b]=x;coordinates[b+1]=y;
  }
}
function pathPointAt(coordinates:readonly number[],distances:readonly number[],distance:number):[number,number]{
  let i=1;while(i<distances.length-1&&distances[i]<distance)i++;
